'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dvander = require( './../lib/dvander.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dvander, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 8', function test( t ) {
	t.strictEqual( dvander.length, 8, 'has expected arity' );
	t.end();
});

tape( 'the function generates a Vandermonde matrix (row-major, decreasing)', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	out = new Float64Array( 9 );

	dvander( 'row-major', -1, 3, 3, x, 1, out, 3 );

	expected = new Float64Array([
		1.0,
		1.0,
		1.0,
		4.0,
		2.0,
		1.0,
		9.0,
		3.0,
		1.0
	]);

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function generates a Vandermonde matrix (row-major, increasing)', function test( t ) {
	var expected;
	var out;
	var x;

	x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	out = new Float64Array( 9 );

	dvander( 'row-major', 1, 3, 3, x, 1, out, 3 );

	expected = new Float64Array([
		1.0,
		1.0,
		1.0,
		1.0,
		2.0,
		4.0,
		1.0,
		3.0,
		9.0
	]);

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

