tape( 'the function returns the output array', function test( t ) {
	var out;
	var x;
	var v;

	x = new Float64Array( [ 1.0, 2.0 ] );
	out = new Float64Array( 4 );

	v = dvander( 'row-major', -1, 2, 2, x, 1, out, 2 );

	t.strictEqual( v, out, 'returns expected value' );
	t.end();
});

tape( 'if provided an `M` equal to `0`, the function early returns', function test( t ) {
	var out;
	var x;

	x = new Float64Array( [] );
	out = new Float64Array( [] );

	dvander( 'row-major', -1, 0, 3, x, 1, out, 3 );

	t.deepEqual( out, new Float64Array( [] ), 'returns expected value' );
	t.end();
});

tape( 'if provided an `N` equal to `0`, the function early returns', function test( t ) {
	var out;
	var x;

	x = new Float64Array( [ 1.0, 2.0 ] );
	out = new Float64Array( [] );

	dvander( 'row-major', -1, 2, 0, x, 1, out, 0 );

	t.deepEqual( out, new Float64Array( [] ), 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying a stride (row-major)', function test( t ) {
	var expected;
	var out;
	var x;

	// Pick every other element: x[0]=1.0, x[2]=3.0
	x = new Float64Array( [ 1.0, 0.0, 3.0, 0.0 ] );
	out = new Float64Array( 6 );

	dvander( 'row-major', -1, 2, 3, x, 2, out, 3 );

	expected = new Float64Array( [ 1.0, 1.0, 1.0, 9.0, 3.0, 1.0 ] );

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying a negative stride (row-major)', function test( t ) {
	var expected;
	var out;
	var x;

	// Negative stride: starts from last and goes backward
	x = new Float64Array( [ 3.0, 0.0, 1.0 ] );
	out = new Float64Array( 6 );

	dvander( 'row-major', -1, 2, 3, x, -2, out, 3 );

	// x[2]=1.0 (first), x[0]=3.0 (second)
	expected = new Float64Array( [ 1.0, 1.0, 1.0, 9.0, 3.0, 1.0 ] );

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

